              "During works, erosion and sediment control materials must be available onsite at all times and must be installed if sedimentation is likely to occur into the stream (e.g. silt fences, straw bale dikes, settling basins, ditch blocks, or filter cloth). A contingency plan must be developed outlining the measures to be taken by workers when carrying out any work to control erosion and sediment. All erosion and sediment control devices must be regularly inspected and maintained to remain functional during works. These devices and any accumulated sediment must be removed from the site after the completion of works;",
            condition_category_code: "ELC",
            parent_standard_permit_condition_id: 510,
            parent_permit_condition_id: 510,
            condition_type_code: "CON",
